CREATE    VIEW [FO].[vwProductCategories]
AS
SELECT 
	T1.[RECID],
	T2.[NAME] AS [PRODUCTCATEGORYHIERARCHYNAME],
	T1.[RECID] AS [CATEGORYRECORDID],
	T3.[CODE] AS [PARENTPRODUCTCATEGORYCODE],
	T3.[NAME] AS [PARENTPRODUCTCATEGORYNAME],
	T1.[CODE] AS [CATEGORYCODE],
	T1.[NAME] AS [CATEGORYNAME],
	T5.[DESCRIPTION] AS [CATEGORYDESCRIPTION],
	T7.[CATEGORYNAME] AS [PROJECTCATEGORYNAME],
	T1.[DEFAULTPROJECTGLOBALCATEGORY] AS [DEFAULTPROJECTGLOBALCATEGORYID]

FROM [synapse_fo].[ECORESCATEGORY] T1
	CROSS JOIN [synapse_fo].[ECORESCATEGORYHIERARCHY] T2
	LEFT OUTER JOIN [synapse_fo].[ECORESCATEGORY] T3 ON (
		(T1.PARENTCATEGORY = T3.RECID)
		AND (T1.PARTITION = T3.PARTITION)
		)
	LEFT OUTER JOIN [synapse_fo].[ECORESCATEGORYSYSTEMLANGUAGE_RICS] T4 ON (
			(T1.RECID = T4.CATEGORY)
			AND (T1.PARTITION = T4.PARTITION)
			)
	LEFT OUTER JOIN [synapse_fo].[ECORESCATEGORYTRANSLATION] T5 ON (
			(
				(T1.RECID = T5.CATEGORY)
				AND (T1.PARTITION = T5.PARTITION)
				)
			AND (
				(T4.SYSTEMLANGUAGEID = T5.LANGUAGEID)
				AND (T4.PARTITION = T5.PARTITION)
				)
			)
	LEFT OUTER JOIN [synapse_fo].[PROCCATEGORYMODIFIER] T6 ON (
			(T1.RECID = T6.CATEGORY)
			AND (T1.PARTITION = T6.PARTITION)
			)
	LEFT OUTER JOIN [synapse_fo].[SHAREDCATEGORY] T7 ON (
			(T1.DEFAULTPROJECTGLOBALCATEGORY = T7.RECID)
			AND (T1.PARTITION = T7.PARTITION)
			)

WHERE (
		(T2.HIERARCHYMODIFIER = 1)
		AND (
			(T1.CATEGORYHIERARCHY = T2.RECID)
			AND (T1.PARTITION = T2.PARTITION)
			)
		)
